-- Import into an EMPTY utf8mb4 database. MySQL 8 / MariaDB 10.4+; PHP 8.2+.
CREATE TABLE schema_versions (version INT PRIMARY KEY, installed_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP) ENGINE=InnoDB;
CREATE TABLE roles (id INT AUTO_INCREMENT PRIMARY KEY, name VARCHAR(100) NOT NULL UNIQUE, permissions TEXT NOT NULL) ENGINE=InnoDB;
CREATE TABLE teachers (id INT AUTO_INCREMENT PRIMARY KEY, tazkira_type VARCHAR(20) NOT NULL DEFAULT 'not_available', tazkira_number VARCHAR(160) NULL, tazkira_volume VARCHAR(160) NULL, tazkira_page VARCHAR(160) NULL, tazkira_registration VARCHAR(160) NULL, tazkira_province VARCHAR(160) NULL, tazkira_issue_date DATE NULL, public_code VARCHAR(32) UNIQUE, photo_path VARCHAR(40), name VARCHAR(160) NOT NULL, phone VARCHAR(40), qualifications TEXT, subjects TEXT, joining_date DATE NOT NULL, status VARCHAR(20) NOT NULL DEFAULT 'active') ENGINE=InnoDB;
CREATE TABLE employees (id INT AUTO_INCREMENT PRIMARY KEY, public_code VARCHAR(32) UNIQUE, photo_path VARCHAR(40), name VARCHAR(160) NOT NULL, father_name VARCHAR(160) NOT NULL, job_title VARCHAR(160) NOT NULL, department VARCHAR(160), phone VARCHAR(40), address TEXT, dob DATE NULL, gender VARCHAR(20), joining_date DATE NOT NULL, end_date DATE NULL, monthly_salary DECIMAL(14,2) NOT NULL DEFAULT 0, status VARCHAR(20) NOT NULL DEFAULT 'active', notes TEXT, tazkira_type VARCHAR(20) NOT NULL DEFAULT 'not_available', tazkira_number VARCHAR(160) NULL, tazkira_volume VARCHAR(160) NULL, tazkira_page VARCHAR(160) NULL, tazkira_registration VARCHAR(160) NULL, tazkira_province VARCHAR(160) NULL, tazkira_issue_date DATE NULL) ENGINE=InnoDB;
CREATE TABLE users (id INT AUTO_INCREMENT PRIMARY KEY, employee_id INT NULL UNIQUE, photo_path VARCHAR(40), username VARCHAR(80) NOT NULL UNIQUE, name VARCHAR(160) NOT NULL, password_hash VARCHAR(255) NOT NULL, role_id INT NOT NULL, teacher_id INT NULL, active TINYINT NOT NULL DEFAULT 1, auth_version INT NOT NULL DEFAULT 1, FOREIGN KEY(employee_id) REFERENCES employees(id), FOREIGN KEY(role_id) REFERENCES roles(id), FOREIGN KEY(teacher_id) REFERENCES teachers(id)) ENGINE=InnoDB;
CREATE TABLE login_attempts (id BIGINT AUTO_INCREMENT PRIMARY KEY, login_key CHAR(64) NOT NULL, happened_at DATETIME NOT NULL, INDEX(login_key,happened_at)) ENGINE=InnoDB;
CREATE TABLE audit (id BIGINT AUTO_INCREMENT PRIMARY KEY, actor_id INT NULL, action VARCHAR(80) NOT NULL, entity VARCHAR(80) NOT NULL, record_id BIGINT NULL, details TEXT, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, INDEX(created_at)) ENGINE=InnoDB;
CREATE TABLE settings (name VARCHAR(80) PRIMARY KEY, value TEXT NOT NULL) ENGINE=InnoDB;
CREATE TABLE programs (id INT AUTO_INCREMENT PRIMARY KEY, name VARCHAR(160) NOT NULL, description TEXT, status VARCHAR(20) NOT NULL DEFAULT 'active') ENGINE=InnoDB;
CREATE TABLE subjects (id INT AUTO_INCREMENT PRIMARY KEY, name VARCHAR(160) NOT NULL, program_id INT NULL, status VARCHAR(20) NOT NULL DEFAULT 'active', FOREIGN KEY(program_id) REFERENCES programs(id)) ENGINE=InnoDB;
CREATE TABLE rooms (id INT AUTO_INCREMENT PRIMARY KEY, name VARCHAR(100) NOT NULL UNIQUE, capacity INT NOT NULL, status VARCHAR(20) NOT NULL DEFAULT 'active') ENGINE=InnoDB;
CREATE TABLE batches (id INT AUTO_INCREMENT PRIMARY KEY, name VARCHAR(160) NOT NULL, program_id INT NOT NULL, level VARCHAR(100), start_date DATE NOT NULL, end_date DATE NOT NULL, capacity INT NOT NULL, fee DECIMAL(14,2) NOT NULL DEFAULT 0, status VARCHAR(20) NOT NULL DEFAULT 'active', FOREIGN KEY(program_id) REFERENCES programs(id)) ENGINE=InnoDB;
CREATE TABLE class_subjects (id INT AUTO_INCREMENT PRIMARY KEY, batch_id INT NOT NULL, subject_id INT NOT NULL, teacher_id INT NOT NULL, required TINYINT NOT NULL DEFAULT 1, UNIQUE(batch_id,subject_id), FOREIGN KEY(batch_id) REFERENCES batches(id), FOREIGN KEY(subject_id) REFERENCES subjects(id), FOREIGN KEY(teacher_id) REFERENCES teachers(id)) ENGINE=InnoDB;
CREATE TABLE students (id INT AUTO_INCREMENT PRIMARY KEY, tazkira_type VARCHAR(20) NOT NULL DEFAULT 'not_available', tazkira_number VARCHAR(160) NULL, tazkira_volume VARCHAR(160) NULL, tazkira_page VARCHAR(160) NULL, tazkira_registration VARCHAR(160) NULL, tazkira_province VARCHAR(160) NULL, tazkira_issue_date DATE NULL, public_code VARCHAR(32) UNIQUE, photo_path VARCHAR(40), name VARCHAR(160) NOT NULL, father_name VARCHAR(160) NOT NULL, dob DATE NULL, gender VARCHAR(20), phone VARCHAR(40), address TEXT, guardian VARCHAR(160), guardian_relation VARCHAR(80), guardian_phone VARCHAR(40), registered_date DATE NOT NULL, status VARCHAR(20) NOT NULL DEFAULT 'active', notes TEXT, INDEX(name), INDEX(phone)) ENGINE=InnoDB;
CREATE TABLE enrollments (id INT AUTO_INCREMENT PRIMARY KEY, student_id INT NOT NULL, batch_id INT NOT NULL, start_date DATE NOT NULL, end_date DATE NULL, status VARCHAR(20) NOT NULL DEFAULT 'active', UNIQUE(student_id,batch_id), FOREIGN KEY(student_id) REFERENCES students(id), FOREIGN KEY(batch_id) REFERENCES batches(id)) ENGINE=InnoDB;
CREATE TABLE timetable (id INT AUTO_INCREMENT PRIMARY KEY, class_subject_id INT NOT NULL, room_id INT NOT NULL, weekday INT NOT NULL, start_time TIME NOT NULL, end_time TIME NOT NULL, start_date DATE NOT NULL, end_date DATE NOT NULL, FOREIGN KEY(class_subject_id) REFERENCES class_subjects(id), FOREIGN KEY(room_id) REFERENCES rooms(id), INDEX(weekday,start_date,end_date)) ENGINE=InnoDB;
CREATE TABLE holidays (id INT AUTO_INCREMENT PRIMARY KEY, name VARCHAR(160) NOT NULL, date DATE NOT NULL UNIQUE) ENGINE=InnoDB;
CREATE TABLE attendance (id BIGINT AUTO_INCREMENT PRIMARY KEY, enrollment_id INT NOT NULL, class_subject_id INT NOT NULL, date DATE NOT NULL, status VARCHAR(20) NOT NULL, UNIQUE(enrollment_id,class_subject_id,date), FOREIGN KEY(enrollment_id) REFERENCES enrollments(id), FOREIGN KEY(class_subject_id) REFERENCES class_subjects(id)) ENGINE=InnoDB;
CREATE TABLE accounts (id INT AUTO_INCREMENT PRIMARY KEY, name VARCHAR(100) NOT NULL UNIQUE, opening_balance DECIMAL(14,2) NOT NULL DEFAULT 0) ENGINE=InnoDB;
CREATE TABLE charges (id BIGINT AUTO_INCREMENT PRIMARY KEY, enrollment_id INT NOT NULL, kind VARCHAR(30) NOT NULL, description VARCHAR(255) NOT NULL, amount DECIMAL(14,2) NOT NULL, due_date DATE NOT NULL, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY(enrollment_id) REFERENCES enrollments(id)) ENGINE=InnoDB;
CREATE TABLE credits (id BIGINT AUTO_INCREMENT PRIMARY KEY, charge_id BIGINT NOT NULL, amount DECIMAL(14,2) NOT NULL, reason VARCHAR(255) NOT NULL, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY(charge_id) REFERENCES charges(id)) ENGINE=InnoDB;
CREATE TABLE receipts (id BIGINT AUTO_INCREMENT PRIMARY KEY, student_id INT NOT NULL, account_id INT NOT NULL, amount DECIMAL(14,2) NOT NULL, date DATE NOT NULL, reference VARCHAR(160), token CHAR(64) NOT NULL UNIQUE, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY(student_id) REFERENCES students(id), FOREIGN KEY(account_id) REFERENCES accounts(id)) ENGINE=InnoDB;
CREATE TABLE allocations (id BIGINT AUTO_INCREMENT PRIMARY KEY, receipt_id BIGINT NOT NULL, charge_id BIGINT NOT NULL, amount DECIMAL(14,2) NOT NULL, UNIQUE(receipt_id,charge_id), FOREIGN KEY(receipt_id) REFERENCES receipts(id), FOREIGN KEY(charge_id) REFERENCES charges(id)) ENGINE=InnoDB;
CREATE TABLE refunds (id BIGINT AUTO_INCREMENT PRIMARY KEY, receipt_id BIGINT NOT NULL, allocation_id BIGINT NULL, account_id INT NOT NULL, amount DECIMAL(14,2) NOT NULL, date DATE NOT NULL, reason VARCHAR(255) NOT NULL, token CHAR(64) NOT NULL UNIQUE, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY(receipt_id) REFERENCES receipts(id), FOREIGN KEY(allocation_id) REFERENCES allocations(id), FOREIGN KEY(account_id) REFERENCES accounts(id)) ENGINE=InnoDB;
CREATE TABLE agreements (id INT AUTO_INCREMENT PRIMARY KEY, teacher_id INT NOT NULL, batch_id INT NOT NULL, start_date DATE NOT NULL, end_date DATE NOT NULL, fixed_amount DECIMAL(14,2) NOT NULL DEFAULT 0, percent DECIMAL(5,2) NOT NULL DEFAULT 0, FOREIGN KEY(teacher_id) REFERENCES teachers(id), FOREIGN KEY(batch_id) REFERENCES batches(id)) ENGINE=InnoDB;
CREATE TABLE payroll (id BIGINT AUTO_INCREMENT PRIMARY KEY, teacher_id INT NOT NULL, period CHAR(7) NOT NULL, fixed_amount DECIMAL(14,2) NOT NULL, variable_amount DECIMAL(14,2) NOT NULL, total DECIMAL(14,2) NOT NULL, explanation LONGTEXT NOT NULL, approved_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, UNIQUE(teacher_id,period), FOREIGN KEY(teacher_id) REFERENCES teachers(id)) ENGINE=InnoDB;
CREATE TABLE payroll_sources (id BIGINT AUTO_INCREMENT PRIMARY KEY, payroll_id BIGINT NOT NULL, agreement_id INT NOT NULL, allocation_id BIGINT NULL, refund_id BIGINT NULL, amount DECIMAL(14,2) NOT NULL, UNIQUE(agreement_id,allocation_id), UNIQUE(agreement_id,refund_id), FOREIGN KEY(payroll_id) REFERENCES payroll(id), FOREIGN KEY(agreement_id) REFERENCES agreements(id), FOREIGN KEY(allocation_id) REFERENCES allocations(id), FOREIGN KEY(refund_id) REFERENCES refunds(id)) ENGINE=InnoDB;
CREATE TABLE payroll_payments (id BIGINT AUTO_INCREMENT PRIMARY KEY, payroll_id BIGINT NOT NULL, account_id INT NOT NULL, amount DECIMAL(14,2) NOT NULL, date DATE NOT NULL, token CHAR(64) NOT NULL UNIQUE, FOREIGN KEY(payroll_id) REFERENCES payroll(id), FOREIGN KEY(account_id) REFERENCES accounts(id)) ENGINE=InnoDB;
CREATE TABLE movements (id BIGINT AUTO_INCREMENT PRIMARY KEY, account_id INT NOT NULL, destination_id INT NULL, kind VARCHAR(20) NOT NULL, category VARCHAR(100) NOT NULL, amount DECIMAL(14,2) NOT NULL, date DATE NOT NULL, reason VARCHAR(255) NOT NULL, reversal_of BIGINT NULL UNIQUE, token CHAR(64) NOT NULL UNIQUE, FOREIGN KEY(account_id) REFERENCES accounts(id), FOREIGN KEY(destination_id) REFERENCES accounts(id), FOREIGN KEY(reversal_of) REFERENCES movements(id)) ENGINE=InnoDB;
CREATE TABLE reconciliations (id BIGINT AUTO_INCREMENT PRIMARY KEY, account_id INT NOT NULL, date DATE NOT NULL, expected DECIMAL(14,2) NOT NULL, counted DECIMAL(14,2) NOT NULL, note TEXT, FOREIGN KEY(account_id) REFERENCES accounts(id)) ENGINE=InnoDB;
CREATE TABLE assessments (id INT AUTO_INCREMENT PRIMARY KEY, class_subject_id INT NOT NULL, name VARCHAR(160) NOT NULL, date DATE NOT NULL, max_marks DECIMAL(7,2) NOT NULL, pass_marks DECIMAL(7,2) NOT NULL, weight DECIMAL(7,2) NOT NULL DEFAULT 1, FOREIGN KEY(class_subject_id) REFERENCES class_subjects(id)) ENGINE=InnoDB;
CREATE TABLE marks (id BIGINT AUTO_INCREMENT PRIMARY KEY, assessment_id INT NOT NULL, enrollment_id INT NOT NULL, marks DECIMAL(7,2) NULL, status VARCHAR(20) NOT NULL, UNIQUE(assessment_id,enrollment_id), FOREIGN KEY(assessment_id) REFERENCES assessments(id), FOREIGN KEY(enrollment_id) REFERENCES enrollments(id)) ENGINE=InnoDB;
CREATE TABLE certificates (id BIGINT AUTO_INCREMENT PRIMARY KEY, enrollment_id INT NOT NULL, kind VARCHAR(30) NOT NULL, date DATE NOT NULL, wording TEXT NOT NULL, revoked TINYINT NOT NULL DEFAULT 0, reason VARCHAR(255), print_count INT NOT NULL DEFAULT 0, FOREIGN KEY(enrollment_id) REFERENCES enrollments(id)) ENGINE=InnoDB;
CREATE TABLE employee_payroll (id BIGINT AUTO_INCREMENT PRIMARY KEY, employee_id INT NOT NULL, period CHAR(7) NOT NULL, monthly_salary DECIMAL(14,2) NOT NULL, covered_days INT NOT NULL, month_days INT NOT NULL, total DECIMAL(14,2) NOT NULL, approved_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, UNIQUE(employee_id,period), FOREIGN KEY(employee_id) REFERENCES employees(id)) ENGINE=InnoDB;
CREATE TABLE employee_payroll_payments (id BIGINT AUTO_INCREMENT PRIMARY KEY, employee_payroll_id BIGINT NOT NULL, account_id INT NOT NULL, amount DECIMAL(14,2) NOT NULL, date DATE NOT NULL, reference VARCHAR(160), token CHAR(64) NOT NULL UNIQUE, FOREIGN KEY(employee_payroll_id) REFERENCES employee_payroll(id), FOREIGN KEY(account_id) REFERENCES accounts(id)) ENGINE=InnoDB;
INSERT INTO schema_versions(version) VALUES(1);
